import * as React from "react"
import { Link } from "gatsby"
import { StaticImage } from "gatsby-plugin-image"
import { ArrowRight } from "./Icons"
import { useStartCta } from "../lib/start-cta"
import * as s from "./CtaBand.module.css"

const CtaBand = () => {
  const cta = useStartCta()

  return (
  <section className={s.band} id="get-started">
    <div className={s.texture}>
      <StaticImage
        src="../images/blueprint-texture.jpg"
        alt=""
        placeholder="dominantColor"
        layout="fullWidth"
        quality={60}
      />
    </div>

    <div className="container">
      <p className={`eyebrow ${s.eyebrow}`}>
        {cta.signedIn ? "Pick up where you left off" : "Ready to get started?"}
      </p>

      <h2 className={s.title}>
        Get Your <span className="hl">Free Contractor Tools</span> Today
      </h2>

      <p className={s.copy}>
        Join thousands of contractors who are already using our free services to grow their
        business.
      </p>

      <Link to={cta.to} className="btn btn--lg">
        {cta.label}
        <ArrowRight className="btn__arrow" />
      </Link>

      {cta.signedIn ? null : <p className={s.note}>No credit card required. Start in minutes.</p>}
    </div>
  </section>
  )
}

export default CtaBand
