import * as React from "react"
import { Link } from "gatsby"
import { Check, ArrowRight } from "./Icons"
import { useStartCta } from "../lib/start-cta"
import * as s from "./Hero.module.css"

const BENEFITS = [
  "100% Free to Use",
  "No Hidden Fees",
  "Built for Contractors",
]

const Hero = () => {
  const cta = useStartCta()

  return (
    <section className={s.hero}>
      <div className={`container ${s.inner}`}>
        <div className={s.content}>
          <p className={s.eyebrow}>
            BUILD <span>|</span> CONNECT <span>|</span> GROW
          </p>

          <h1 className={s.title}>
            Free Tools to
            <br />
            Grow Your
            <br />
            <span>Contracting Business</span>
          </h1>

          <p className={s.lead}>
            Get a professional website, domain email and QR codes
            — all for free. Simple, powerful tools designed
            specifically for contractors.
          </p>

          <ul className={s.benefits}>
            {BENEFITS.map(item => (
              <li key={item}>
                <span className={s.check}>
                  <Check />
                </span>

                <span>{item}</span>
              </li>
            ))}
          </ul>

          <Link to={cta.to} className={s.cta}>
            <span>{cta.label}</span>
            <ArrowRight />
          </Link>

          {/* A reassurance for somebody deciding whether to start; somebody already in does not need it. */}
          {cta.signedIn ? null : (
            <p className={s.trust}>
              No credit card required. Start in minutes.
            </p>
          )}
        </div>
      </div>

      <div className={s.mobileVisual} aria-hidden="true" />
    </section>
  )
}

export default Hero