import * as React from "react"
import Header from "../components/Header"
import Hero from "../components/Hero"
import Services from "../components/Services"
import WhyUs from "../components/WhyUs"
import CtaBand from "../components/CtaBand"
import Seo from "../components/Seo"
import { HOME } from "../config/share"

/* What search engines are told about the site, so the home page can be shown with its tools listed
   underneath it. It is a hint, not an order: the search engine decides what it shows, and only after it
   has read the pages. The tools named here are the ones in the header, each on a page of its own. */
const SITE = "https://freecontractorservices.com"
const TOOLS = [
  { name: "Website Builder", path: "/website-builder/" },
  { name: "Invoice Builder", path: "/invoice-builder/" },
  { name: "QR Code Generator", path: "/qr-codes/" },
  { name: "Free Contractor Website", path: "/website/" },
]
const SCHEMA = {
  "@context": "https://schema.org",
  "@graph": [
    { "@type": "Organization", "@id": `${SITE}/#organization`, name: "Free Contractor Services", url: `${SITE}/` },
    { "@type": "WebSite", "@id": `${SITE}/#website`, url: `${SITE}/`, name: "Free Contractor Services", publisher: { "@id": `${SITE}/#organization` } },
    {
      "@type": "ItemList",
      "@id": `${SITE}/#tools`,
      name: "Free tools for contractors",
      itemListElement: TOOLS.map((t, i) => ({
        "@type": "SiteNavigationElement",
        position: i + 1,
        name: t.name,
        url: `${SITE}${t.path}`,
      })),
    },
  ],
}

const IndexPage = () => (
  <>
    <Header />
    <main data-print="hide">
      <Hero />
      <Services />
      <WhyUs />
      <CtaBand />
    </main>
  </>
)

export const Head = () => <Seo fullTitle={HOME.title} description={HOME.description} path="/" schema={SCHEMA} />

export default IndexPage
